"""Case013 display: recorded variant quality and blocked packed correspondence."""
from html import escape
from pathlib import Path
import importlib.util
from common import read, require, sha

C13='cases/013-dualquant-reference-quality'
FIGURES={f'assets/case013-{name}':C13+'/figures/'+name for name in ('ppl.svg','dev-success.svg','packed-gates.svg')}
SECTIONS=('overview','implementation','results','analysis','cost','reproduce','report')
SOURCE_COPIES={
    'case013-report-en.md.txt':C13+'/REPORT.md', 'case013-report-ko.md.txt':C13+'/REPORT.ko.md',
    'case013-reproduction-en.md.txt':C13+'/REPRODUCTION.md', 'case013-reproduction-ko.md.txt':C13+'/REPRODUCTION.ko.md',
    'case013-notice.md.txt':C13+'/NOTICE.md','case013-solver.py.txt':C13+'/source/paper_int4.py',
    'case013-codec.py.txt':C13+'/source/reference_int4.py','case013-runner.py.txt':C13+'/source/paper_model_runner.py',
    'case013-audit.py.txt':C13+'/analysis/audit.py','case013-tests.py.txt':C13+'/tests/test_records.py',
    'case013-method-contract.md.txt':C13+'/METHOD_CONTRACT.md','case013-evaluation.md.txt':C13+'/EVALUATION_PROTOCOL.md',
    'case013-failures.md.txt':C13+'/FAILURE_ANALYSIS.md','case013-packed-probe.md.txt':C13+'/PACKED_PROBE.md',
    'case013-roadmap.md.txt':C13+'/ROADMAP.md',
}

def load_case013(root:Path):
    case=root/C13
    if not (case/'README.md').exists():return None
    spec=importlib.util.spec_from_file_location('case013_display_derive',case/'publication/derive.py')
    mod=importlib.util.module_from_spec(spec);spec.loader.exec_module(mod)
    data=read(case/'summary/project.json')
    require(data==mod.derive(case),'Case013 projection differs from saved records')
    names=[C13+'/summary/project.json',C13+'/provenance/PUBLIC_MANIFEST.json',*SOURCE_COPIES.values(),*FIGURES.values(),
           *(C13+'/'+name for name in data['source_identity'])]
    return {**data,'sources':{name:sha(root/name) for name in names},
            'evidence_kind':'RECORDED_INT4_REFERENCE_VARIANT_NOT_FORMAL_SERVING'}

def a(url,label):return '<a href="'+escape(url,quote=True)+'">'+escape(label)+'</a>'
def table(headers,rows,label):
    return '<div class="scroll" role="region" tabindex="0" aria-label="'+escape(label)+'"><table><thead><tr>'+''.join('<th scope="col">'+escape(str(h))+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+escape(str(x))+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'

def figure(name,alt,caption):
    return '<figure><img style="max-width:100%;height:auto" src="../assets/case013-'+name+'" alt="'+escape(alt,quote=True)+'"><figcaption>'+escape(caption)+'</figcaption></figure>'

def home_case013(data,lang):
    ko=lang=='ko'
    return ('<section class="panel" id="dualquant-study"><p class="eyebrow">CASE 013 · INT4 REFERENCE QUALITY</p><h2>'
        +('모델 압축 오차를 줄이면 답변과 도구 작업도 좋아질까?' if ko else 'Does lower compression error improve answers and tool tasks?')+'</h2><p>'
        +('모델 가중치를 실제 4-bit 파일로 저장·복원하는 실행기와 품질 비교 도구를 구현했습니다. 같은 질문에서 문장 확률 점수·장문 답변·실제 도구 작업의 완료 여부를 비교합니다. 모델 압축 검증과 에이전트 실패 분석에 관련된 작업입니다.' if ko else 'Implemented actual 4-bit weight storage/reload and quality-comparison tools. Matched questions reveal changes in language scores, long answers and completed tool actions. This work relates to compression validation and agent-failure analysis.')+'</p><p>'
        +('작은 모델의 확률 점수는 좋아졌지만, 4B에서는 도구 작업 성공이 줄었습니다. 가중치 오차 감소와 실제 답변 개선은 같은 결과가 아니었습니다.' if ko else 'Probability scores improved in the small model, while tool-task success decreased in 4B. Lower weight error did not consistently improve real answers.')+'</p><p class="scope">'
        +('Qwen 두 모델 · RTX 5080 · 16비트(BF16) 복원 뒤 품질 확인 · 4비트 압축 계산의 전체 모델 오차 기준 미통과' if ko else 'Two Qwen models · RTX 5080 · Quality after 16-bit (BF16) reconstruction · Full 4-bit packed-model error gate not met')+'</p><div class="actions">'
        +a('case013.html#overview','쉽게 살펴보기' if ko else 'Overview')+' · '
        +a('case013.html#implementation','구현 코드' if ko else 'Implementation')+' · '
        +a('case013.html#results','전체 결과' if ko else 'Results')+'</div></section>')

def render_case013(data,lang):
    ko=lang=='ko';txt=lambda en,korean:korean if ko else en
    labels=['한눈에 보기','구현','실험과 결과','해석','시간·메모리','CPU 검산','보고서·출처'] if ko else ['Overview','Implementation','Experiment and results','Interpretation','Time and memory','CPU checks','Report and sources']
    out='<header><p class="eyebrow">DIOVA · CASE 013</p><h1>'+txt('Does Lower Compression Error Improve Answers and Tool Tasks?','모델 압축 오차를 줄이면 답변과 도구 작업도 좋아질까?')+'</h1><p class="lede">'+txt('Implemented 4-bit storage/reload of learned model values (weights), plus answer/tool evaluators to check whether compression preserves real tasks as well as language scores. This work relates to matched-input model quality checks and agent-failure analysis.','압축한 모델이 문장 점수뿐 아니라 실제 작업도 유지하는지 확인하려고, 모델이 학습한 숫자(가중치)를 4비트로 저장·복원하고 답변·도구 실행을 평가하는 도구를 구현했습니다. 같은 입력에서 결과를 비교하는 모델 품질 검사와 에이전트 실패 분석에 관련된 작업입니다.')+'</p></header>'
    out+='<nav aria-label="'+txt('Page contents','페이지 목차')+'"><ol>'+''.join('<li>'+a('#'+key,label)+'</li>' for key,label in zip(SECTIONS,labels))+'</ol></nav>'
    def section(i,body):return '<section class="panel study-section" id="'+SECTIONS[i]+'"><h2>'+labels[i]+'</h2>'+body+'</section>'
    out+=section(0,'<p>'+txt('Question: can more accurate compressed weights improve actual answers and tool use?','질문: 더 정확하게 압축한 가중치가 실제 답변과 도구 사용도 개선할까요?')+'</p><p>'+txt('RTN rounds weights to the nearest representable value as a baseline. Both models had lower weight error with D16 than RTN. PPL improved in 0.6B but slightly worsened in 4B; free-agent success also fell in 4B.','RTN은 가중치를 가장 가까운 표현값으로 반올림한 비교 기준입니다. D16의 가중치 오차는 RTN보다 두 모델 모두 작았습니다. 0.6B의 PPL은 좋아졌지만 4B에서는 조금 나빠졌고, 자유 도구 작업의 성공도 줄었습니다.')+'</p><p>'+txt('PPL summarizes next-token probabilities; lower is better, and it is not accuracy. KL measures how the vocabulary probabilities differ from the original model. Agent success requires the correct final answer and actual required actions such as edits and checks. DEV below means existing tasks used during development, not an independent new test.','PPL은 다음 토큰에 준 확률을 요약한 점수로 낮을수록 좋습니다. 정답률이 아닙니다. KL은 원래 모델과 후보가 어휘에 주는 확률 분포의 차이입니다. 에이전트 성공은 최종 답뿐 아니라 필요한 파일 수정·검사 같은 실제 행동도 완료했는지 확인합니다. 아래 DEV는 개발 중 조정에 쓰던 기존 문제이며 독립된 새 시험이 아닙니다.')+'</p>')
    out+=section(1,'<ol><li>'+txt('Original weights → update row/column scale factors in groups of 64','원래 가중치 → 64개 묶음(group64)의 행·열 배율(scale) 조정')+'</li><li>'+txt('4-bit integer codes + scale factors → packed files → reload','4비트 정수값(INT4 code) + 배율(scale) → 묶음 저장(packed) → 다시 불러오기')+'</li><li>'+txt('Same token inputs → BF16 / RTN / D16 / D4 → scores and outputs','같은 토큰 입력 → BF16 / RTN / D16 / D4 → 점수와 출력')+'</li></ol><p>'+txt('D16 and D4 share the same INT4 weight files. D16 uses 16-bit floating-point (BF16) inputs with column rescaling; D4 additionally quantizes input activations to INT4. The 16 and 4 distinguish input precision, not weight bits. Embeddings, attention, norms and KV precision retain the original paths.','D16과 D4는 같은 4비트 정수(INT4) 가중치 파일을 씁니다. D16은 입력을 16비트 부동소수점(BF16)으로 계산하며 열 배율을 적용합니다. D4는 여기에 입력 활성값의 INT4 양자화를 추가합니다. D16의 16과 D4의 4는 가중치 비트 수가 아니라 입력 정밀도를 구분합니다. Embedding·attention·norm·KV 정밀도는 원래 경로를 유지합니다.')+'</p><p>'+txt('This reference variant is a quality-check calculation implemented from public equations, separate from the authors’ complete private-library program. It reconstructs BF16 weights for BF16 matrix operations, so quality results do not establish packed-kernel speedup.','공개 수식을 바탕으로 한 품질 확인용 계산(reference variant)을 직접 구현했습니다. 원저자의 비공개 라이브러리 전체 실행과는 다릅니다. 가중치를 BF16으로 복원해 BF16 행렬 연산으로 품질을 확인했으므로 실제 압축 커널의 가속 증거와 구분합니다.')+'</p><div class="actions">'+a('../sources/case013-solver.py.txt',txt('Solver and adapter','가중치 변환과 모델 연결 코드(adapter)'))+' · '+a('../sources/case013-codec.py.txt',txt('Packed-value storage codec','저비트 묶음 저장·해독 코드(codec)'))+' · '+a('../sources/case013-runner.py.txt',txt('Model and tool runner','모델·도구 실행기'))+'</div>')
    quality=table(['Model','Method','PPL ↓','KL ↓'],[[x['model'],x['method'],f"{x['ppl']:.3f}",f"{x['forward_KL_BF16_to_candidate']:.3f}"] for x in data['quality']],txt('All four methods in both models','두 모델에서 모든 네 방법의 비교'))
    quality+=figure('ppl.svg',txt('Separate Qwen model panels of PPL for four methods','네 방법의 PPL을 Qwen 모델별로 나눈 두 그림'),txt('Lower PPL is better; descriptive subset scores, no confidence intervals.','PPL은 낮을수록 좋습니다. 일부 데이터의 관측 점수이며 신뢰구간은 없습니다.'))
    amap={(x['cohort'],x['method'],x['mode']):x for x in data['agents']}
    atable=table(['Method',txt('Base free','기본 문제의 직접 도구 실행'),txt('16K free','16K 입력의 직접 도구 실행')],[[m,*[f"{amap[(c,m,'FREE')]['successes']}/{amap[(c,m,'FREE')]['n']}" for c in ['base','extension16k']]] for m in ['BF16','RTN','D16','D4']],txt('Free tool tasks','자유 도구 작업'))
    atable+=figure('dev-success.svg',txt('Exact long-task and separate replay/free DEV success counts','정확 일치 장문 답안과 기존 문제(DEV)의 재생·직접 실행 성공 수'),txt('k/n DEV counts; length variants share task IDs and are not independent samples.','개발에 쓰던 문제(DEV)의 성공 수/전체 수입니다. 길이만 바꾼 문제는 같은 task ID를 공유하며 독립 표본으로 합치지 않습니다.'))
    lmap={(x['method'],x['length']):f"{x['successes']}/{x['n']}" for x in data['long']}
    ltable=table(['Method','8K exact','16K exact','32K exact'],[[m,*[lmap.get((m,l),txt('Not run: policy','미실행: 정책')) for l in [8192,16384,32768]]] for m in ['BF16','RTN','D16','D4']],txt('Exact long-input task scores','장문 답안의 정확 일치 점수'))
    out+=section(2,'<p>'+txt('Each model/method scores 65,504 positions in 32 × 2,048-token WikiText-2 subset windows. The same windows are reused across methods; this is not full benchmark PPL.','각 모델/방법은 WikiText-2 일부 32 × 2,048-token 구간에서 65,504위치를 채점합니다. 방법 간 같은 구간을 재사용하며 전체 benchmark PPL은 아닙니다.')+'</p>'+quality+'<h3>'+txt('Free tool use','직접 도구를 고르는 작업')+'</h3>'+atable+'<p>'+txt('Eight unique development (DEV) tasks; the 16K follow-up reuses four. Reading supplied tool results (replay) passed in every condition and is separate from choosing and executing tools. Results below use the original tool contract. The model guide separately describes the follow-up restricting tool names to an allowed list and improving rejection feedback.','개발에 쓰던 고유 문제(DEV)는 8개이며 16K 후속은 그중 4개의 길이 변경본입니다. 이미 주어진 도구 결과만 읽는 재생(replay)은 모든 조건에서 정답이었습니다. 직접 도구를 고르고 실행하는 점수와 구분합니다. 아래는 원래 도구 계약의 결과이며, 도구 이름을 허용 목록으로 제한하고 거절 이유를 개선한 후속은 모델별 안내의 도구 실패 완화에서 별도로 확인할 수 있습니다.')+'</p><details><summary>'+txt('Exact long-input answers and missing cells','장문 답안의 정확 일치 결과와 미실행 조건')+'</summary>'+ltable+'<p>'+txt('Twelve unique tasks. Candidate 32K cells were skipped by a conservative memory policy after measuring 16K workspace; these are not OOM failures.','고유 문제는 12개입니다. 후보 32K는 16K에서 작업용 메모리(workspace)를 관측한 뒤 보수적인 사용 한도 때문에 실행하지 않았습니다. 메모리 부족(OOM)으로 실패한 결과가 아닙니다.')+'</p></details>')
    out+=section(3,'<p>'+txt('A small change in a language score can coexist with errors in tool names or action sequences. D16 used CamelCase tool names on two fixture-edit tasks, repeated rejected calls and claimed completion without the required edit.','작은 문장 점수 변화와 도구 이름·행동 오류가 함께 나타날 수 있습니다. D16은 두 파일 수정 작업에서 도구 이름을 CamelCase로 쓰고 거절된 호출을 반복한 뒤 실제 수정 없이 완료를 주장했습니다.')+'</p><p>'+txt('Post-hoc reading also separates a correct numeric expression from the frozen exact-answer contract. Primary scores were not relaxed afterwards. These small DEV observations are not formal noninferiority results.','사후 분석에서는 계산값이 맞는 표현과 미리 정한 정확 일치 답변 규칙(exact)을 구분했습니다. 이후 주 점수 기준을 완화하지 않았습니다. 개발에 쓰던 작은 문제 집합(DEV)의 관측이며, 품질이 뒤지지 않는다는 통계적 입증은 아닙니다.')+'</p>')
    costs=table(['Model','Method',txt('Saved-file bytes','저장 파일 바이트'),txt('Quality evaluation elapsed (s)','품질 평가 경과 시간 (초)')],[[x['model'],x['method'],'N/A' if x['method']=='BF16' else f"{x['artifact_payload_bytes']:,}",f"{x['quality_wall_seconds']:.3f}"] for x in data['quality']],txt('Recorded storage and quality-loop costs','기록된 저장량과 품질 loop 비용'))
    out+=section(4,figure('packed-gates.svg',txt('Different tensor-relative errors; the full model exceeds its 0.02 limit','배열(tensor)별 상대 오차: 전체 모델은 기준0.02를 넘음'),txt('Linear scale; normalize each tensor by its own reference energy. Not a layer-error trajectory.','선형 축이며 각 배열(tensor)의 기준 출력 제곱합(reference energy)으로 나눕니다. 층을 따라 변하는 오차를 그린 그림이 아닙니다.'))+'<p>'+txt('Projection-file bytes include integer codes and scale factors, not the full model checkpoint or runtime GPU memory. The elapsed NLL evaluation time includes measurement transfers and some file I/O; it is not request response time.','변환한 선형층의 저장 파일(projection artifact)은 정수값(code)과 배율(scale)을 포함하며 전체 모델 파일(checkpoint)이나 실행 중 GPU 메모리(VRAM)가 아닙니다. NLL 평가 경과 시간은 계측 전송·일부 입출력을 포함하며 실제 요청 응답 시간은 아닙니다.')+'</p><details><summary>'+txt('Recorded bytes and quality-loop times','기록된 파일 바이트와 품질 평가 시간')+'</summary>'+costs+'</details><p>'+txt('Actual packed Marlin GEMM and one block passed. Full-model relative error was ','실제 압축 가중치를 쓰는 Marlin 행렬 곱(GEMM)과 한 블록은 검사를 통과했지만 전체 모델 상대 오차는 ')+f"{100*data['packed']['relative_rmse']:.2f}%"+txt(' against a ','로, 사전 기준 ')+f"{100*data['packed']['threshold']:.0f}%"+txt(' limit. Serving speedup and capacity gains remain unestablished.','를 넘었습니다. 실제 요청 처리 속도나 더 긴 문맥 처리의 이득은 아직 확인하지 못했습니다.')+'</p>')
    command='python3 -B '+C13+'/analysis/audit.py --output /tmp/case013-audit.json\npython3 -B -m unittest discover -s '+C13+'/tests -v'
    out+=section(5,'<p>'+txt('With NumPy installed, recalculate recorded NLL/PPL, predicted-ID flips, exact answers and required tool actions. No model or GPU is loaded.','NumPy로 저장된 정답 확률 손실(NLL)·PPL, 예측 ID 변경, 정확 일치 답안, 필요한 도구 실행 여부를 다시 계산합니다. 모델·GPU를 로드하지 않습니다.')+'</p><pre>'+escape(command)+'</pre><p>'+a('../sources/case013-reproduction-'+lang+'.md.txt',txt('Dependencies and rerun requirements','의존성과 재실행 요건'))+' · '+a('../sources/case013-audit.py.txt',txt('Independent scalar audit','별도 계산 코드로 수치 검산'))+' · '+a('../sources/case013-tests.py.txt',txt('CPU contract tests','CPU 실행 규칙 테스트'))+'</p>')
    out+=section(6,'<p>'+a('../sources/case013-report-'+lang+'.md.txt',txt('Full report','정식 보고서'))+' · '+a('../data/case013.json',txt('Numbers and source file-content hashes','수치와 출처 파일 내용 대조값(hash)'))+' · '+a('../sources/case013-notice.md.txt',txt('References and contributions','출처·기여'))+'</p><p>'+a('../sources/case013-method-contract.md.txt',txt('Paper/code/study contract','논문·코드·실행 규칙의 대응'))+' · '+a('../sources/case013-evaluation.md.txt',txt('Scoring protocol','평가 기준'))+' · '+a('../sources/case013-failures.md.txt',txt('Failures and controls','실패·성공 사례'))+' · '+a('../sources/case013-packed-probe.md.txt',txt('Packed technical record','압축 가중치 계산(packed)의 기술 기록'))+' · '+a('../sources/case013-roadmap.md.txt',txt('Proposed follow-up','미실행 후속 계획'))+'</p><p>'+txt('DualQuant is the authors’ method. DIOVA provides the independent INT4 variant, serialization, evaluation and inspection tools. New model runs during publication: zero.','DualQuant는 원저자의 방법입니다. DIOVA는 공개 수식에 따른 별도 INT4 구현과 저장·평가·탐색 도구를 구현했습니다. 이번 공개 정리에서 새 모델 실행은 0입니다.')+'</p>')
    return out+'<p>'+a('#overview',txt('Back to overview','한눈에 보기로 돌아가기'))+'</p>'
